def multiply_matrix(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
                C[i][j] %= mod
    return C

def matrix_power(matrix, power, mod):
    result = [[int(i == j) for j in range(len(matrix))] for i in range(len(matrix))]
    while power > 0:
        if power % 2 == 1:
            result = multiply_matrix(result, matrix, mod)
        matrix = multiply_matrix(matrix, matrix, mod)
        power //= 2
    return result

